package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string // PIC X(4) @0 len=4
	TcF decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsC decimal.Decimal // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 // PIC 99 len=2 = 0
var WsCount int64 // PIC 99 len=2 = 0
var WsFEd string // PIC ZZ9.9 len=5
var WsCEd string // PIC -ZZ9.99 len=7

var TempRecVar TempRec

var inputLines []string
var inputIdx int
var inputOpen bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parsePic9V9(field string, dec int) decimal.Decimal {
	// field contains digits only (or spaces if padded short line)
	digits := ""
	for _, ch := range field {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		} else if ch == ' ' {
			continue
		} else if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	// strip leading zeros for parsing but keep at least one
	var n int64
	for _, ch := range digits {
		n = n*10 + int64(ch-'0')
	}
	return decimal.New(n, int32(-dec))
}

// Format unsigned ZZ9.9 : intDigits=3, decDigits=1
func formatZZ9_9(v decimal.Decimal) string {
	// truncate toward zero to 1 decimal (values already at that scale)
	t := v.Truncate(1)
	neg := t.IsNegative()
	av := t
	if neg {
		av = t.Neg()
	}
	// scale to integer of 1 decimal
	scaled := av.Mul(decimal.NewFromInt(10))
	// scaled should be integer
	i := scaled.IntPart()
	intPart := i / 10
	fracPart := i % 10
	if intPart < 0 {
		intPart = -intPart
	}
	// keep low-order digits that fit
	intPart = intPart % 1000
	d0 := intPart / 100
	d1 := (intPart / 10) % 10
	d2 := intPart % 10
	chars := make([]byte, 3)
	digits := []int64{d0, d1, d2}
	// Z suppression: leading zeros become spaces
	// find first non-zero among positions that are Z (first 2)
	// 9 position always prints
	suppress := true
	for idx := 0; idx < 2; idx++ {
		if digits[idx] != 0 {
			suppress = false
		}
		if suppress && digits[idx] == 0 {
			// check if any later integer digit before the 9 is non-zero?
			// For ZZZ-like, need to look ahead: if all remaining int digits (up to 9) are zero, suppress.
			allZero := true
			for k := idx + 1; k < 3; k++ {
				if digits[k] != 0 {
					allZero = false
					break
				}
			}
			if allZero {
				chars[idx] = ' '
			} else {
				// actually if later digit non-zero, this zero should print? In COBOL Z suppression,
				// zeros after first non-zero print. Since we are still in suppress zone and current is zero
				// but a later digit is non-zero, current should be space? No: leading zeros -> spaces.
				// e.g., 5 with ZZ9 -> "  5": both leading zeros spaces.
				// e.g., 50 -> " 50". So space.
				chars[idx] = ' '
			}
		} else {
			chars[idx] = byte('0' + digits[idx])
			suppress = false
		}
	}
	// last integer digit (9) always
	chars[2] = byte('0' + digits[2])
	var sb strings.Builder
	sb.WriteByte(chars[0])
	sb.WriteByte(chars[1])
	sb.WriteByte(chars[2])
	sb.WriteByte('.')
	sb.WriteByte(byte('0' + fracPart))
	return sb.String()
}

// Format signed -ZZ9.99 : sign + intDigits=3, decDigits=2
func formatMinusZZ9_99(v decimal.Decimal) string {
	t := v.Truncate(2)
	neg := t.IsNegative()
	av := t
	if neg {
		av = t.Neg()
	}
	scaled := av.Mul(decimal.NewFromInt(100))
	i := scaled.IntPart()
	intPart := i / 100
	fracPart := i % 100
	if intPart < 0 {
		intPart = -intPart
	}
	if fracPart < 0 {
		fracPart = -fracPart
	}
	intPart = intPart % 1000
	d0 := intPart / 100
	d1 := (intPart / 10) % 10
	d2 := intPart % 10
	f0 := fracPart / 10
	f1 := fracPart % 10
	chars := make([]byte, 3)
	digits := []int64{d0, d1, d2}
	for idx := 0; idx < 2; idx++ {
		if digits[idx] == 0 {
			allZero := true
			for k := idx + 1; k < 3; k++ {
				if digits[k] != 0 {
					allZero = false
					break
				}
			}
			_ = allZero
			chars[idx] = ' '
		} else {
			chars[idx] = byte('0' + digits[idx])
			// fill remaining Z positions that were spaces? No, leading only.
			// Mark subsequent Z's to print zeros
			for k := idx + 1; k < 2; k++ {
				// will be handled in loop; need to know suppression ended
				// Use sentinel: set digits check? Simplest: break and handle rest
				_ = k
			}
			// fill rest Z positions with digits
			for k := idx + 1; k < 2; k++ {
				chars[k] = byte('0' + digits[k])
			}
			// prevent overwriting: set loop to end
			// set remaining to done by marking
			for k := 0; k < idx; k++ {
			}
			// force loop to skip: set idx to end via manual
			// Since we are in for loop, we need to skip ahead. Just set a flag.
			// Easiest: after this, continue loop but force print.
			// We'll set d0/d1 to force non-space: use a separate flag.
			// To avoid complexity, recompute with standard algorithm:
			break
		}
	}
	// Recompute correctly with suppression flag:
	suppress := true
	for idx := 0; idx < 2; idx++ {
		if suppress && digits[idx] == 0 {
			chars[idx] = ' '
		} else {
			chars[idx] = byte('0' + digits[idx])
			suppress = false
		}
		// if this digit was non-zero, subsequent zeros must print
		if digits[idx] != 0 {
			suppress = false
		}
	}
	// Actually above loop already handles: once non-zero seen, suppress=false, later zeros print.
	// But our earlier break logic duplicated; the second loop overwrites correctly.
	chars[2] = byte('0' + digits[2])
	sign := byte(' ')
	if neg {
		sign = '-'
	}
	var sb strings.Builder
	sb.WriteByte(sign)
	sb.WriteByte(chars[0])
	sb.WriteByte(chars[1])
	sb.WriteByte(chars[2])
	sb.WriteByte('.')
	sb.WriteByte(byte('0' + f0))
	sb.WriteByte(byte('0' + f1))
	return sb.String()
}

func formatPIC99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func READ_PARA() {
	if !inputOpen || inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	rec := padRight(line, 8)
	TempRecVar.TcSensor = rec[0:4]
	TempRecVar.TcF = parsePic9V9(rec[4:8], 1)
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	// Exact integer arithmetic: D = TC-F * 10, tInt = (D-320)*50, cents = round(tInt/9) half away from zero
	dScaled := TempRecVar.TcF.Mul(decimal.NewFromInt(10)).Truncate(0).IntPart()
	tInt := (dScaled - 320) * 50
	absT := tInt
	if absT < 0 {
		absT = -absT
	}
	q := absT / 9
	r := absT % 9
	if 2*r >= 9 {
		q++
	}
	var cents int64
	if tInt < 0 {
		cents = -q
	} else {
		cents = q
	}
	// store into S9(3)V99: keep low-order digits
	if cents > 99999 || cents < -99999 {
		m := cents % 100000
		cents = m
	}
	WsC = decimal.New(cents, -2)

	if WsC.IsNegative() {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatZZ9_9(TempRecVar.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	fmt.Fprint(os.Stdout, TempRecVar.TcSensor+" "+WsFEd+"F "+WsCEd+"C\n")
	READ_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT TEMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// If file does not exist, treat as empty (AT END immediately)
		inputLines = nil
		inputOpen = true
		inputIdx = 0
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 0, 64*1024), 1024*1024)
		var lines []string
		for sc.Scan() {
			t := sc.Text()
			// strip trailing \r if CRLF
			if len(t) > 0 && t[len(t)-1] == '\r' {
				t = t[:len(t)-1]
			}
			lines = append(lines, t)
		}
		f.Close()
		inputLines = lines
		inputOpen = true
		inputIdx = 0
	}
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE TEMP-FILE
	inputOpen = false
	fmt.Fprint(os.Stdout, "READINGS: "+formatPIC99(WsCount)+" BELOW ZERO: "+formatPIC99(WsFreeze)+"\n")
}

func main() {
	WsEofFlag = "N"
	WsC = decimal.NewFromInt(0)
	WsFreeze = 0
	WsCount = 0
	MAIN_PARA()
}
